import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const sidebar = tv({
  slots: {
    root: "flex h-full w-full flex-col gap-6 border-border bg-raised p-4",
    section: "flex flex-col gap-1",
    sectionLabel: "px-2 pb-1 font-mono text-xs font-bold tracking-widest uppercase",
    list: "flex flex-col gap-0.5",
    item: "flex",
    link: [
      "flex min-h-11 w-full items-center gap-3 border-l-4 border-transparent px-3",
      "font-medium text-foreground",
      "hover:border-border hover:bg-surface",
      "aria-[current=page]:border-border aria-[current=page]:bg-secondary aria-[current=page]:font-bold",
      focusRing,
    ],
    icon: "size-5 shrink-0",
    badge: "ml-auto",
  },
  variants: {
    size: {
      sm: { root: "gap-4 p-3", link: "text-sm" },
      md: { root: "gap-6 p-4", link: "text-base" },
      lg: { root: "gap-8 p-5", link: "text-lg" },
    },
    bordered: {
      true: { root: "border-r-3" },
    },
  },
  defaultVariants: {
    size: "md",
    bordered: true,
  },
});

export type SidebarVariants = VariantProps<typeof sidebar>;

"use client";

import { sidebar, type SidebarVariants } from "@/lib/beton/recipes/sidebar.recipe";
import { createContext, useContext, type ComponentProps, type ReactNode } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

type Styles = ReturnType<typeof sidebar>;

const SidebarContext = createContext<Styles>(sidebar());

function useStyles() {
  return useContext(SidebarContext);
}

export interface SidebarProps extends ComponentProps<"nav">, SidebarVariants {
  render?: RenderProp;
}

function SidebarRoot({
  size = "md",
  bordered = true,
  className,
  "aria-label": ariaLabel = "Sidebar",
  render,
  ...props
}: SidebarProps) {
  const styles = sidebar({ size, bordered });
  return (
    <SidebarContext.Provider value={styles}>
      {renderElement(
        "nav",
        { ...props, "aria-label": ariaLabel, className: styles.root({ class: className }) },
        render,
      )}
    </SidebarContext.Provider>
  );
}

export interface SidebarSectionProps extends Omit<ComponentProps<"div">, "title"> {
  /** A heading above the group of links. */
  title?: ReactNode;
  render?: RenderProp;
}

function SidebarSection({ className, title, children, render, ...props }: SidebarSectionProps) {
  const styles = useStyles();
  return renderElement(
    "div",
    {
      ...props,
      className: styles.section({ class: className }),
      children: (
        <>
          {title ? <p className={styles.sectionLabel()}>{title}</p> : null}
          <ul className={styles.list()}>{children}</ul>
        </>
      ),
    },
    render,
  );
}

export interface SidebarItemProps extends ComponentProps<"a"> {
  /** Marks the page you are on. Sets `aria-current="page"`. */
  active?: boolean;
  /** Shown before the label. */
  icon?: ReactNode;
  /** Shown at the end of the row, such as a count. */
  badge?: ReactNode;
  /** Classes for the surrounding list item. */
  itemClassName?: string;
  render?: RenderProp;
}

function SidebarItem({
  className,
  itemClassName,
  active = false,
  icon,
  badge,
  children,
  render,
  ...props
}: SidebarItemProps) {
  const styles = useStyles();
  return (
    <li className={styles.item({ class: itemClassName })}>
      {renderElement(
        "a",
        {
          ...props,
          "aria-current": active ? "page" : undefined,
          className: styles.link({ class: className }),
          children: (
            <>
              {icon ? <span className={styles.icon()}>{icon}</span> : null}
              {children}
              {badge ? <span className={styles.badge()}>{badge}</span> : null}
            </>
          ),
        },
        render,
      )}
    </li>
  );
}

/** The column of links down the side of an application. */
export const Sidebar = Object.assign(SidebarRoot, {
  Section: SidebarSection,
  Item: SidebarItem,
});
